pub fn split_off(&mut self, at: usize) -> Self {
    let mut new_map = VecMap::new();

    // Ensure the `at` index is within bounds
    if at < self.n {
        // Move elements from the original map to the new map
        for i in at..self.n {
            if let Some(value) = self.v[i].take() {
                new_map.insert(value);
            }
        }
        // Update the original map's size
        self.n = at;
    }

    new_map
}
